import java.io.*;

public class Main {
    private static final FastScanner reader = new FastScanner(System.in);
    private static final PrintWriter writer = new PrintWriter(
            new BufferedWriter(new OutputStreamWriter(System.out)));

    public static void main(String[] args) throws Exception {
        int n = reader.nextInt();
        int k = reader.nextInt();

        int nn = n;
        long ex = 1;

        while (n % 10 == 0) {
            n /= 10;
            k--;
        }

        while (k > 0) {
            if (n % 2 == 0) {
                ex *= 5;
                n /= 2;
                k--;
            } else if (n % 5 == 0) {
                ex *= 2;
                n /= 5;
                k--;
            } else {
                break;
            }
        }

        while (k > 0) {
            ex *= 10;
            k--;
        }

        writer.println(ex * nn);
        writer.flush();
    }

    private static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[10 * 1024];
        private int position;
        private int length;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (position >= length) {
                length = input.read(buffer);
                position = 0;
                if (length == -1) {
                    return -1;
                }
            }
            return buffer[position++];
        }

        int nextInt() throws IOException {
            int c;
            int result = 0;

            do {
                c = read();
                if (c == -1) {
                    return result;
                }
            } while (c < '0' || c > '9');

            result = c - '0';

            while (true) {
                c = read();
                if (c < '0' || c > '9') {
                    return result;
                }
                result = result * 10 + c - '0';
            }
        }
    }
}

